import { Component, OnInit, ChangeDetectorRef, Input, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { GovBrSelectModule } from '@serpro/ngx-dsgovbr';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MonacoEditorModule } from 'ngx-monaco-editor-v2';
import { DadosCalculadoraService } from '../../services/dados-calculadora.service';
import { XmlService } from '../../services/xml.service';
import { DispositivoService } from '../../services/dispositivo.service';
import { Subscription } from 'rxjs';
import { TooltipDirective } from "ngx-bootstrap/tooltip";

@Component({
  selector: 'gerador-validador-xml',
  templateUrl: './gerador-validador-xml.component.html',
  styleUrl: './gerador-validador-xml.component.scss',
  standalone: true,
  providers: [],
  imports: [
    CommonModule,
    ReactiveFormsModule,
    GovBrSelectModule,
    MonacoEditorModule,
    TooltipDirective
]
})
export class GeradorValidadorXmlComponent implements OnInit, OnDestroy {

  editorOptions = {
    theme: 'vs-light',
    language: 'xml',
    automaticLayout: true,
    minimap: { enabled: false },
    overviewRulerLanes: 0,
    hideCursorInOverviewRuler: true,
    overviewRulerBorder: false,
    scrollBeyondLastLine: false,
    fontSize: 14,
    wordWrap: 'on',
    stickyScroll: { enabled: false }
  };

  xmlCode: string = '';
  output?: any;
  form!: FormGroup;
  resposta: any = null;
  erro: any = null;
  placeholder!: string;

  sucesso: string = '';

  @Input() json!: any;
  @Input() xml!: any;
  @Input() tipoValues: any = null;
  @Input() subtipo: 'GRUPO' | 'NOTA' = 'GRUPO';
  @Input() modo: 'gerador' | 'validador' = 'validador';

  private subscriptions: Subscription = new Subscription();
  dispositivo: string = '';


  constructor(
    private readonly formBuilder: FormBuilder,
    private dadosCalculadoraService: DadosCalculadoraService,
    private xmlService: XmlService,
    private cdr: ChangeDetectorRef,
    private dispositivoService: DispositivoService,
  ) {

  }

  ngOnInit(): void {
    this.output = this.dadosCalculadoraService.output;
    
    // Create form with conditional tipoControl
    const formControls: any = {
      xmlControl: [{ value: this.xmlCode, disabled: false }, [Validators.required]]
    };
    
    if (this.tipoValues != null && this.tipoValues.length > 0) {
      formControls.tipoControl = [{ value: this.tipoValues[0].mnemonico, disabled: false }, [Validators.required]];
    }
    
    this.form = this.formBuilder.group(formControls);
    this.confirmar();
  
    this.setSubscriptions();
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  setSubscriptions() {
    this.subscriptions.add(
      this.dispositivoService.dispositivo$.subscribe((dispositivo: any) => {
        this.dispositivo = dispositivo;
        if (this.dispositivo === 'device-xsmall') {

        } else {

        }
      }));
  }

  copiar() {
    const currentValue = this.form.get('xmlControl')?.value || '';
    if (currentValue) {
      navigator.clipboard.writeText(currentValue).then(() => {
      }).catch(err => {
      });
    }
  }

  colar() {
    navigator.clipboard.readText().then(text => {
      this.form.patchValue({ xmlControl: text });
      this.xmlCode = text; // Atualiza o código XML exibido
    }).catch(err => {
    });
  }

  apagar() {
    this.form.patchValue({ xmlControl: '' });
    this.xmlCode = ''; // Limpa o código XML exibido
    this.resposta = null;
    this.erro = null;
  }

  validar() {

    const xml: string = this.form.get('xmlControl')?.value;
    let tipo: string = 'nfe'; // default value
    const subtipo: string = this.subtipo;

    // Get tipo from form control if it exists
    if (this.tipoValues != null && this.form.get('tipoControl')) {
      const tipoValue = this.form.get('tipoControl')?.value;
      tipo = tipoValue || tipo;
    }

    if (xml == '' || xml == null || tipo == '' || tipo == null) {
      this.erro = { detail: 'XML e tipo são obrigatórios para validação.' };
      this.resposta = null;
      return;
    }

    this.xmlService.validarXml(xml, tipo, subtipo).subscribe({
      next: (response) => {
        this.resposta = response;
        this.erro = null;
        this.sucesso = 'Sucesso na validação do XML.';
      },
      error: (error) => {
        this.erro = error?.error || 'Erro desconhecido na validação do XML';
        this.resposta = null;
      }
    });
  }

  organizarXml(xml: string): string {
    const xmlFormatado = this.xmlService.organizarXml(xml);
    return xmlFormatado;
  }

  organizar() {
    const currentValue = this.form.get('xmlControl')?.value || '';
    const formattedXml = this.organizarXml(currentValue);
    this.form.patchValue({ xmlControl: formattedXml });
    this.xmlCode = formattedXml;
  }

  confirmar() {
    this.form.patchValue({ xmlControl: '' }); // Limpa o valor atual
    this.resposta = null;
    this.erro = null;
    if (this.output == null) {
      return;
    }

    let tipo: string = 'nfe';
    const subtipo: string = this.subtipo;

    // Get tipo from form control if it exists
    if (this.tipoValues != null && this.form.get('tipoControl')) {
      const tipoValue = this.form.get('tipoControl')?.value;
      tipo = tipoValue || tipo;
    }

    this.xmlService.gerarXml(this.output, tipo).subscribe({
      next: (response) => {
        this.erro = null;
        const formattedXml = this.organizarXml(response);
        this.form.patchValue({ xmlControl: formattedXml });
        this.xmlCode = formattedXml;
        this.resposta = true;
        this.cdr.detectChanges();
        this.dadosCalculadoraService.xml = formattedXml; // Atualiza o XML no serviço
        this.sucesso = 'Sucesso na geração do XML.';
      },
      error: (error) => {
        alert('Erro na geração do XML.');
        this.erro = error?.error || {detail: 'Erro desconhecido na geração do XML'};
        this.erro = JSON.parse(this.erro);
        this.resposta = null;
        this.form.patchValue({ xmlControl: '' });
        this.xmlCode = '';
        this.cdr.detectChanges();
      }
    });
  }

  onSubmit(action: string) {
    if (action === 'validar') {
      this.validar();
    } else if (action === 'restaurar') {
      this.restaurar();
    }
  }

  restaurar() {
    this.confirmar();
  }

  getVersaoNotaTecnica(): string {
    const tipoSelecionado = this.form?.get('tipoControl')?.value;
    if (!tipoSelecionado || !this.tipoValues) {
      return '';
    }
    const documento = this.tipoValues.find((item: any) => item.mnemonico === tipoSelecionado);
    return documento ? documento.versaoNotaTecnica : '';
  }

}
