import { HttpClient, HttpHeaders, HttpParams } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable, of } from "rxjs";
import { environment } from "../../environments/environment";
import xmlFormatter from 'xml-formatter';

@Injectable({
  providedIn: 'root'
})
export class XmlService {
  private baseUrl = environment.APIEndpoint;

  // tipos de documento em cache
  public tiposDeDocumentoValidacao: any[] = [];
  public tiposDeDocumentoGeracao: any[] = [];

  constructor(private http: HttpClient) { }

  validarXml(xmlString: string, tipo: string, subtipo: string): Observable<any> {
    const headers = new HttpHeaders({
      'Content-Type': 'application/xml'
    });
    let params: HttpParams = new HttpParams();
    params = params.append('tipo', tipo);
    params = params.append('subtipo', subtipo);
    return this.http.post<any>(`${this.baseUrl}/calculadora/xml/validate`, xmlString, { headers, params });
  }

  gerarXml(body: any, tipo: string): Observable<any> {
    const headers = new HttpHeaders({
      'Content-Type': 'application/json',
      'Accept': 'application/xml'
    });
    let params: HttpParams = new HttpParams();
    params = params.append('tipo', tipo);
    return this.http.post<any>(`${this.baseUrl}/calculadora/xml/generate`, body, { headers, responseType: 'text' as 'json', params });
  }

  organizarXml(xml: string): string {
    let formattedXml = xmlFormatter(xml, {
      indentation: '  ',
      filter: (node) => true,
      lineSeparator: '\n',
    });
    formattedXml = this.inlineEmptyTags(formattedXml);
    return formattedXml;
  }

  obterDocumentosNaGeracao(): Observable<any[]> {
    return this.http.get<any[]>(`${this.baseUrl}/calculadora/xml/generate`);
  }

  obterDocumentosNaValidacao(): Observable<any[]> {
    return this.http.get<any[]>(`${this.baseUrl}/calculadora/xml/validate`);
  }

  private inlineEmptyTags(xml: string): string {
    // para substituir tags que não possuem filhos e contêm apenas texto
    return xml.replace(/<([a-zA-Z0-9]+)>\s*([^<]*)\s*<\/\1>/g, (match, tagName, value) => {
      return `<${tagName}>${value.trim()}</${tagName}>`; // para manter na mesma linha
    });
  }

}